INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19001, 'Jeremiah 48:34', 'Jeremiah', 48, 34, '&nbsp;د هغوئ د ژړا آوازونه د حسبون نه تر اِلى‌عالى او يهض پورې، او د ضُعر نه تر حورونايم پورې او عجلت‌شليشياه پورې اورېدلے شى. او تر دې چې اوس د نِمريم اوبۀ هم اوچې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19002, 'Jeremiah 48:35', 'Jeremiah', 48, 35, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به په موآب کښې هغه کسان ختم کړم څوک چې په اوچتو ځايونو کښې خپلو معبودانو ته نذرانې پېش کوى او هغوئ ته خوشبوئى سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19003, 'Jeremiah 48:36', 'Jeremiah', 48, 36, '&nbsp;نو زما زړۀ د موآب دپاره لکه د شپيلۍ فريادونه کوى، او دا هم په قير‌حراست کښې د هغه خلقو دپاره لکه د شپيلۍ فريادونه کوى. کوم مال دولت چې هغوئ حاصل کړے وو لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19004, 'Jeremiah 48:37', 'Jeremiah', 48, 37, '&nbsp;ټولو خلقو خپل سرونه او ږيرې د غم په وجه ګنجى کړى وُو، او خپل لاسونه يې زخمى کړى وُو او د خپلو ملاګانو نه يې ټاټ تاو کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19005, 'Jeremiah 48:38', 'Jeremiah', 48, 38, '&nbsp;مالِک خُدائ فرمائى چې، د موآب د هر يو کور په سر او په هره لاره او کوڅه کښې ماتم او ژړا اورېدلے کيږى. ځکه چې ما موآب لکه د هغه لوښى په شان چې څوک يې هم نۀ غواړى ټوټه ټوټه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19006, 'Jeremiah 48:39', 'Jeremiah', 48, 39, '&nbsp;هاے هاے، دا څنګه ټوټه ټوټه شو. او د هغوئ چغې او سورى واورئ. د موآب شرمېدل وګورئ، دا خو ټولو خلقو او ګاونډيانو دپاره د خندا او د تباهۍ يو مثال جوړ شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19007, 'Jeremiah 48:40', 'Jeremiah', 48, 40, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”ګورئ، يو قوم د باز په شان خپلې وزرې خورې کړې او په موآب باندې راغوټه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19008, 'Jeremiah 48:41', 'Jeremiah', 48, 41, '&nbsp;قريوت به قبضه شى او د هغۀ مضبوطې قلعه ګانې به واخستلے شى. او په هغه ورځ به د موآب د فوجيانو زړونه داسې ګبراويږى لکه چې د يوې ښځې زړۀ چې د لنګون په وخت کښې ګبراويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19009, 'Jeremiah 48:42', 'Jeremiah', 48, 42, '&nbsp;موآب به نور يو قوم پاتې نۀ شى ځکه چې هغوئ خپل ځان د مالِک خُدائ نه لوئ تصور کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19010, 'Jeremiah 48:43', 'Jeremiah', 48, 43, '&nbsp;مالِک خُدائ فرمائى چې، دهشت، کنده او دامونه د موآب د خلقو په انتظار کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19011, 'Jeremiah 48:44', 'Jeremiah', 48, 44, '&nbsp;هر څوک چې د دهشت نه وتښتى نو په کنده کښې به وغورزيږى. څوک چې د کندې نه راوچت شى نو په دام کښې به ګرفتار شى، ځکه چې زۀ په موآب باندې د سزا وخت راولم، مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19012, 'Jeremiah 48:45', 'Jeremiah', 48, 45, '&nbsp;کوم خلق چې حسبون ته د پناه دپاره وتښتى نو هلته به بې‌وسه ودريږى، ځکه چې د حسبون نه د اور شُغلې راوچتيږى، د بادشاه سيحون د زوړ کور نه به د اور لمبې راوچتيږى. دا اور د موآب تندے سوزوى، او د شور اچوونکو لافوانو کوپړۍ سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19013, 'Jeremiah 48:46', 'Jeremiah', 48, 46, '&nbsp;په تا دې افسوس وى اے موآبه. د کموس بُت عبادت کوونکى تباه شول، ستاسو زامن مُلک بدر شول او ستاسو لوڼه ونيولے شوې او جلاوطن کړے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19014, 'Jeremiah 48:47', 'Jeremiah', 48, 47, '&nbsp;خو زۀ به بيا موآب په راتلونکى وخت کښې دوباره بحال کړم، مالِک خُدائ فرمائى.“ نو دلته د موآب په حقله د يرمياه نبى پېشګوئې ختمه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19015, 'Jeremiah 49:1', 'Jeremiah', 49, 1, '&nbsp;د عمونيانو په حقله مالِک خُدائ فرمائى چې، ”آيا د بنى اِسرائيلو څوک اولاد نشته؟ او د هغوئ څوک وارث نشته؟ نو بيا ولې د مولک بُت تابعدارى کوونکو د جاد په مال حال قبضه کړې ده او د هغوئ په ښارونو کښې اوسيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19016, 'Jeremiah 49:2', 'Jeremiah', 49, 2, '&nbsp;مالِک خُدائ فرمائى، ”خو هغه ورځې راروانې دى کله چې زۀ به د عمونيانو د ربه د ښار خلاف د جنګ آواز وکړم. دا ښار به د تباهۍ نه د خاورو يو ډېرے جوړ شى، او د خوا او شا کلى به يې وسوزولے شى. نو بيا به بنى اِسرائيل هغه کسان وشړى چا چې دوئ شړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19017, 'Jeremiah 49:3', 'Jeremiah', 49, 3, '&nbsp;اے د حسبون ښځو، وژاړئ، ځکه چې د عى ښار تباه شو. اے د ربه ښځو، وير وکړئ. د ټاټ جامې واغوندئ او ماتم وکړئ. اخوا ديخوا سرګردانه وزغلئ، ځکه چې د مولک بُت به سره د خپلو اِمامانو او خادِمانو جلاوطن کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19018, 'Jeremiah 49:4', 'Jeremiah', 49, 4, '&nbsp;تاسو ولې په خپل لوئ طاقت باندې فخر او لافې کوئ؟ ستاسو مال دولت به کم کړے شى، اے عمونه. چې د سرکشه جينۍ په شان په خپل مال دولت باندې يقين کوئ او داسې وايئ، په چا کښې جرأت شته چې په مونږ باندې حمله وکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19019, 'Jeremiah 49:5', 'Jeremiah', 49, 5, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، ”ګورئ، زۀ به ستاسو د هرې خوا نه په تاسو باندې يره او وحشت راولم. او ستاسو هر يو کس به د مُلک نه وشړلے شى، او هيڅ څوک به هم دا مفروران يو ځائ ته راجمع نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19020, 'Jeremiah 49:6', 'Jeremiah', 49, 6, '&nbsp;خو وروستو به زۀ عمونيان يو ځل بيا بحال کړم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19021, 'Jeremiah 49:7', 'Jeremiah', 49, 7, '&nbsp;د ادوميانو په حقله مالِک خُدائ ربُ الافواج داسې فرمائى چې، ”ولې په تيمان کښې نور حکمت او عقل نشته څۀ؟ آيا هوښياران ورته صحيح مشوره نۀ شى ورکولے څۀ؟ ولې د هغوئ عقل خوړلے شوے دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19022, 'Jeremiah 49:8', 'Jeremiah', 49, 8, '&nbsp;اے د ددان خلقو، واپس شئ او وتښتئ، او په غارونو کښې خپل ځان پټ کړئ، ځکه چې زۀ په عِيسو افت نازلوم نو په دغه وخت کښې به زۀ هغۀ ته هم سزا ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19023, 'Jeremiah 49:9', 'Jeremiah', 49, 9, '&nbsp;هغوئ څوک چې انګور راټولوى لږ څۀ غريبانانو ته پرېږدى. کۀ چرې په شپه کښې ورباندې غلۀ راشى، نو هغوئ به ورنه هر څۀ نۀ جارُو کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19024, 'Jeremiah 49:10', 'Jeremiah', 49, 10, '&nbsp;خو زۀ به د عِيسو نه هر څۀ جارُو کړم او د هغۀ پټ ځايونه به ښکاره کړم، نو هغه به يو ځائ هم خپل ځان پټولے نۀ شى. د هغۀ ماشومان، خپلوان، او ګاونډيان به تباه کړے شى، او هغه به نور په دُنيا کښې ژوندى پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19025, 'Jeremiah 49:11', 'Jeremiah', 49, 11, '&nbsp;خو زۀ به ستاسو د يتيمانو خيال ساتم او ستاسو کونډې دې هم په ما د مدد دپاره باور وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19026, 'Jeremiah 49:12', 'Jeremiah', 49, 12, '&nbsp;مالِک خُدائ فرمائى چې، ”کۀ چرې بې‌ګناه خلقو ته سزا ملاويږى، نو بيا به تاسو د څومره سزا لائق يئ. تاسو به بې‌سزا پاتې نۀ شئ. نو تاسو به ضرور د غضب د دې پيالۍ نه خوند واخلئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19027, 'Jeremiah 49:13', 'Jeremiah', 49, 13, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ په خپل ذات قسم خورم چې، د بُصره ښار به تباه شى او د خاورو ډېرے به جوړ شى او د ټولو خلقو دپاره به د وحشت، سپکوالى او د لعنت مثال وګرځى، او د هغۀ ټول ښارونه به د تل دپاره تباه او برباد شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19028, 'Jeremiah 49:14', 'Jeremiah', 49, 14, '&nbsp;ما د مالِک خُدائ له طرفه پېغام واورېدو، يو قاصد قومونو ته ولېږلے شو چې هغوئ ته ووائى چې، ”د ادوم په خلاف لښکر راجمع کړئ او د جنګ دپاره تيارى وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19029, 'Jeremiah 49:15', 'Jeremiah', 49, 15, '&nbsp;مالِک خُدائ ادوميانو ته فرمائى چې، اوس به زۀ تا د نورو قومونو په مينځ کښې کمزورے کړم. او ټول به تا ته په سپکه سترګه ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19030, 'Jeremiah 49:16', 'Jeremiah', 49, 16, '&nbsp;ستا خپل دهشت او کوم کبر چې ستا په زړۀ کښې وو تۀ دوکه کړې، تاسو څوک چې د ګټانو په درزونو کښې اوسېږئ، او د غرونو اوچتې څوکې ستا په قبضه کښې دى. کۀ څۀ هم چې تۀ د باز په شان په اوچتو ځايونو کښې خپلې جالې جوړې کړې نو د هلته نه به زۀ تا لاندې راکوز کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19031, 'Jeremiah 49:17', 'Jeremiah', 49, 17, '&nbsp;ادوم به د خلقو دپاره د يرې مثال وګرځى، او څوک هم چې په دې لار تېريږى د هغوئ د ټولو افتونو پورې به حق حېران شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19032, 'Jeremiah 49:18', 'Jeremiah', 49, 18, '&nbsp;لکه څنګه چې سدوم او عموره، او د دې نه ګېرچاپېره ښارونو باندې تباهى راغلې وه، نو ادوم به هم هغه شان تباه شى، هلته به هيڅ څوک نۀ ژوند کوى او نۀ به اوسيږى. مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19033, 'Jeremiah 49:19', 'Jeremiah', 49, 19, '&nbsp;لکه څنګه چې يو زمرے د اُردن د جاړو بوټو نه د څرن زمکې ته راځى او په ګډو ورټوپ کوى، نو دغه شان به زۀ ادوميان د هغوئ د خپل مُلک نه وشړم، او زۀ به د خپلې خوښې مشر په کښې مقرر کړم. نو هغه به په دوئ حکومت وکړى. څوک زما په شان کېدلے شى؟ او يو مشر به هم زما خلاف ونۀ دريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19034, 'Jeremiah 49:20', 'Jeremiah', 49, 20, '&nbsp;نو بيا هغې منصوبې ته غوږ شه کومه چې مالِک خُدائ د ادوم په خلاف جوړه کړې ده، او څۀ چې هغه د تيمان د خلقو سره کول غواړى. د هغوئ د رمې نه به واړۀ ګډورى راکاږى او هغه به په پوره توګه د هغوئ د څرن ځائ د دوئ په وجه وران کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19035, 'Jeremiah 49:21', 'Jeremiah', 49, 21, '&nbsp;د ادوم د راغورزېدو په آواز به زمکه ټوله په لړزان شى، او د هغوئ د چغو او سورو آواز به د بحرِقُلزمه پورې اورېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19036, 'Jeremiah 49:22', 'Jeremiah', 49, 22, '&nbsp;ګورئ، دشمن لکه د باز په شان راغوټه شوے دے، او خپل وزرونه يې په بُصره باندې خوارۀ کړى دى، تر دې چې په هغه ورځ به د ادوم د تکړه فوجيانو زړۀ داسې په تکليف او يره کښې وى لکه چې د يوې ښځې زړۀ په لنګون کښې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19037, 'Jeremiah 49:23', 'Jeremiah', 49, 23, '&nbsp;مالِک خُدائ د دمشق په حقله دا پېغام ورکړو چې، ”د حمات او ارفاد ښارونه د يرې نه اوبۀ شول، ځکه چې هغوئ د خپل ځان د تباهۍ پېغام واورېدو. د هغوئ زړونه داسې بې‌سکونه شول لکه څنګه چې د سمندر چپې نا آرامه او بې‌سکونه وى او هيڅ سکون ورته نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19038, 'Jeremiah 49:24', 'Jeremiah', 49, 24, '&nbsp;د دمشق ښاريه د هغې ښځې په شان ده چې بې‌همته شوه، او د هغې ټول خلق وتښتېدل. يرې، وارخطايۍ، او درد هغه رانيولې ده لکه څنګه چې يوه ښځه د لنګون په وخت کښې نيولې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19039, 'Jeremiah 49:25', 'Jeremiah', 49, 25, '&nbsp;دا مشهور ښار به څومره وران ويجاړ وى، کوم ښار چې په يو وخت کښې د خوشحالۍ ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19040, 'Jeremiah 49:26', 'Jeremiah', 49, 26, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، د هغۀ ځوانان به په کوڅو کښې راپرېوځى او قتل به شى، او د هغوئ فوجيان به په هغه ورځ ټول ختم کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19041, 'Jeremiah 49:27', 'Jeremiah', 49, 27, '&nbsp;زۀ به د دمشق په دېوالونو باندې اور ولګوم، او تر دې چې دا به د بِن‌حدد محلونه وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19042, 'Jeremiah 49:28', 'Jeremiah', 49, 28, '&nbsp;د قيدار او د حاضور د علاقې په حقله کوم چې د بابل بادشاه نبوکدنضر ورباندې حمله وکړه، مالِک خُدائ فرمائى چې، ”راپاڅئ او په قيدار باندې حمله وکړئ او د مشرق اوسېدونکى تباه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19043, 'Jeremiah 49:29', 'Jeremiah', 49, 29, '&nbsp;د هغوئ خېمې او رمې به قبضه کړے شى، د هغوئ د سر سورے به ترې نه سره د سامانه او اوښانو واخستلے شى. او خلق به د هرې خوا نه چغې سورې وهى. او هر چرته به يره خوره شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19044, 'Jeremiah 49:30', 'Jeremiah', 49, 30, '&nbsp;مالِک خُدائ فرمائى چې، اے د حاضور خلقو په منډه وتښتئ. او خپل ځانونه په ژورو غارونو کښې پټ کړئ. ځکه چې د بابل بادشاه نبوکدنضر ستا خلاف منصوبه تياره کړې ده. او ستاسو د تباهۍ تيارے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19045, 'Jeremiah 49:31', 'Jeremiah', 49, 31, '&nbsp;مالِک خُدائ فرمائى، راپاڅه او په هغه ښارونو باندې حمله وکړه څوک چې په آرام او سکون کښې ژوند کوى. د چا چې نۀ دروازې شته او نۀ دېوالونه او يواځې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19046, 'Jeremiah 49:32', 'Jeremiah', 49, 32, '&nbsp;د هغوئ اوښان تالا کړه او د هغوئ رَمې لوټ کړه. او زۀ به هغوئ څوک چې په دشتو او ميرو کښې اوسيږى د هوا په مخکښې خوارۀ کړم او د هرې خوا نه به پرې افت نازل کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19047, 'Jeremiah 49:33', 'Jeremiah', 49, 33, '&nbsp;حاضور به د ګيدړانو د اوسېدو ځائ شى او د همېشه دپاره به وران او شاړ پروت وى. هيڅ څوک به هلته نۀ ژوند کوى او نۀ به اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19048, 'Jeremiah 49:34', 'Jeremiah', 49, 34, '&nbsp;دا د مالِک خُدائ هغه پېغام دے چې په يرمياه نبى باندې د عيلام په حقله د يهوداه د بادشاه صدقياه د بادشاهۍ په وړومبو ورځو کښې نازل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19049, 'Jeremiah 49:35', 'Jeremiah', 49, 35, '&nbsp;مالِک خُدائ ربُ الافواج وفرمائيل چې، ”زۀ به د عيلام ليندې چلوونکى ووژنم، کوم چې د هغوئ د زور او طاقت اُميد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19050, 'Jeremiah 49:36', 'Jeremiah', 49, 36, '&nbsp;زۀ به د آسمانونو د څلورو خوا نه په هغوئ باندې څلور بادونه راولم او هغوئ به ورته تس نس کړم، او داسې يو قوم او مُلک به نۀ وى چې د عيلام خلق ورته په جلاوطنۍ لاړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19051, 'Jeremiah 49:37', 'Jeremiah', 49, 37, '&nbsp;زۀ به د عيلام د خلقو په زړۀ کښې د هغوئ د دشمنانو يره واچوم. څوک چې د هغوئ مرګ پسې ګرځى، زۀ به په هغوئ افت نازل کړم او تر دې چې خپل خطرناک قهر او غضب به پرې راولم. دا د مالِک خُدائ فرمان دے. زۀ به هغوئ ته فوجيان ورولېږم چې دوئ راټينګ کړى تر دې چې ټول تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19052, 'Jeremiah 49:38', 'Jeremiah', 49, 38, '&nbsp;زۀ به خپل تخت په عيلام کښې قائم کړم، او د هغې بادشاه او آفسران به هلاک کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19053, 'Jeremiah 49:39', 'Jeremiah', 49, 39, '&nbsp;خو زۀ به په آئنده کښې د عيلام خلق بحال کړم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19054, 'Jeremiah 50:1', 'Jeremiah', 50, 1, '&nbsp;مالِک خُدائ يرمياه نبى ته د بابل د خلقو او د بابل د وطن په حقله دا پېغام نازل کړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19055, 'Jeremiah 50:2', 'Jeremiah', 50, 2, '&nbsp;”د قومونو په مينځ کښې د دې خبرې اعلان وکړه، جنډا اوچته کړه او په ډاګه ورته ووايه، او هيڅ خبره مۀ پټوه بلکې دا ښکاره وايه چې، بابل به قبضه کړے شى، او بيل بُت به په شرمونو وشرميږى او رسوا به شى، او مردوک بُت به ويريږى. د بابل مجسمه به په شرمونو وشرمولے شى او د هغې بُتان يرې راخستى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19056, 'Jeremiah 50:3', 'Jeremiah', 50, 3, '&nbsp;د شمال د خوا نه به يو قوم په دې حمله وکړى او د هغوئ مُلک به تباه کړى او په صحرا به يې بدل کړى. او هيڅ څوک به هلته نۀ اوسيږى، انسانان او ځناور به وتښتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19057, 'Jeremiah 50:4', 'Jeremiah', 50, 4, '&nbsp;مالِک خُدائ فرمائى چې، ”په هغه ورځو کښې به د اِسرائيل او د يهوداه خلق په يو ځائ په ژړا راروان وى. د مالِک خُدائ او د خپل مقدس خُدائ لټون به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19058, 'Jeremiah 50:5', 'Jeremiah', 50, 5, '&nbsp;هغوئ به د صيون د لارې تپوس وکړى او بيا به هغه خوا ته مخ تاو کړى او ورروان به شى. هغوئ به ما سره ابدى لوظ وکړى کوم به چې کله هم نۀ هېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19059, 'Jeremiah 50:6', 'Jeremiah', 50, 6, '&nbsp;زما غوره شوے قوم د ورکو شوو ګډو په شان دے، د هغوئ د قوم شپونکو هغه په غلطو لارو روان کړى دى او په غرونو کښې يې سرګردانه پرېښودى دى. او هغوئ په غرونو او غونډو سرګردانه ګرځى او خپل د آرام کولو ځائ ترې نه هېر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19060, 'Jeremiah 50:7', 'Jeremiah', 50, 7, '&nbsp;هر چا به چې هم هغوئ بياموندل نو هغوئ به يې وژل. د هغوئ دشمنانو وئيل، مونږ په دوئ باندې په حملې کولو سره ګناه ګار نۀ يُو، ځکه چې هغوئ د مالِک خُدائ خلاف ګناه کړې ده څوک چې رښتينے څرن ځائ دے او د هغوئ پلار نيکۀ به هم په هغۀ باندې يقين او خپل اُميد ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19061, 'Jeremiah 50:8', 'Jeremiah', 50, 8, '&nbsp;اے زما غوره شوے قومه د بابل نه وتښتئ، د بابليانو مُلک پرېږدئ، او د هغه نر چېلى په شان شئ چې د رَمې رهنمائى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19062, 'Jeremiah 50:9', 'Jeremiah', 50, 9, '&nbsp;زۀ به د شمال نه د تکړه قومونو اِتحاد جوړ کړم او د بابل خلاف به يې راپاڅوم. او هغوئ به د بابل خلاف د جنګ دپاره صف بندى وکړى او د شمال د خوا نه به هغه قبضه کړى. او هغوئ په غشو ويشتو کښې ماهران دى چې کله هم د هغوئ غشى نۀ خطا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19063, 'Jeremiah 50:10', 'Jeremiah', 50, 10, '&nbsp;خو بابل به لوټ کړے شى او هر هغه څوک چې هغه لوټ کړى او هر څۀ چې غواړى هغه به يوسى او ځان به پرې موړ کړى. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19064, 'Jeremiah 50:11', 'Jeremiah', 50, 11, '&nbsp;”اے بابليانو تاسو چا چې زما غوره شوے قوم تالا والا کړو، او اوس په خپلو کښې خندا خوشحالى کوئ، تاسو د هغه سخى په شان ټوپونه وهئ کله چې هغه د موږى نه آزاد شى او د آس په شان هڼېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19065, 'Jeremiah 50:12', 'Jeremiah', 50, 12, '&nbsp;خو ستاسو خپله مور به رسوا شى، چا چې تاسو زيږولى يئ هغه به شرمنده شى. هغه به په ټولو مُلکونو کښې بې‌اهميته وى، هغه به په دشتو، په اوچه زمکه، او په صحرا بدله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19066, 'Jeremiah 50:13', 'Jeremiah', 50, 13, '&nbsp;د مالِک خُدائ د غضب په وجه به بيا په کښې څوک نۀ اوسيږى خو بلکل به وران ويجاړ شى. څوک هم چې پرې تېريږى او د بابل تباهى وګورى نو د وحشت نه به حق حېران شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19067, 'Jeremiah 50:14', 'Jeremiah', 50, 14, '&nbsp;اے ليندو والاو تاسو ټولو چا چې خپلې ليندې راښکلى دى، د بابليانو خلاف د جنګ دپاره صف بندى وکړئ. په هغوئ باندې ګزار وکړئ. چې يو غشے درنه خطا نۀ شى. ځکه چې هغوئ د مالِک خُدائ خلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19068, 'Jeremiah 50:15', 'Jeremiah', 50, 15, '&nbsp;د هرې خوا نه د هغۀ خلاف د جنګ چغې ووهئ. وګورئ هغه محاصره شوے دے، د هغۀ دېوالونه راغورزېدلى دى. دا د مالِک خُدائ د انتقام اخستو ورځ ده، د بابل نه انتقام واخلئ. کوم سلوک چې هغوئ د نورو سره کړے وو هم هغه شان سلوک ورسره وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19069, 'Jeremiah 50:16', 'Jeremiah', 50, 16, '&nbsp;د بابل خلق په پټو کښې د تخم کَرلو او فصل رېبلو نه منع کړئ، د ظالمانو د ظلم د وجې نه دې ټول غېر مُلکيان خپلو خلقو او خپل مُلک ته واپس لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19070, 'Jeremiah 50:17', 'Jeremiah', 50, 17, '&nbsp;”بنى اِسرائيل د ګډو د هغه خورې ورې شوې رمې په شان دے چې زمرو په مخه کړې وى. په اول ځل چې چا تېر کړل هغه د اسور بادشاه وو، په آخر کښې چا چې د هغۀ هډُوکى مات کړل هغه نبوکدنضر د بابل بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19071, 'Jeremiah 50:18', 'Jeremiah', 50, 18, '&nbsp;نو په دې وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به اوس د بابل بادشاه او د هغۀ مُلک له سزا ورکړم لکه څنګه چې ما د اسور بادشاه له ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19072, 'Jeremiah 50:19', 'Jeremiah', 50, 19, '&nbsp;زۀ به بنى اِسرائيل خپل د څرن ځائ ته واپس راولم او هغوئ به د کرمل او بسن په پټو کښې وڅريږى، او د هغوئ لوږه به د اِفرائيم او د جِلعاد په غونډو کښې معموره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19073, 'Jeremiah 50:20', 'Jeremiah', 50, 20, '&nbsp;په هغه ورځو کښې، مالِک خُدائ فرمائى چې، د اِسرائيل ګناهونه به ولټولے شى خو يو به په کښې پېدا نۀ شى، او د يهوداه ګناهونه به ولټولے شى او هيڅ ګناه به په کښې پېدا نۀ شى، ځکه چې کوم ما ژوندى پرېښودى دى زۀ به د هغوئ ګناهونه معاف کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19074, 'Jeremiah 50:21', 'Jeremiah', 50, 21, '&nbsp;مالِک خُدائ فرمائى، ”زما لښکرو د مراتايم په وطن او د فقود په خلقو باندې حمله وکړئ. هغوئ پسې شئ، او وې وژنئ او مکمل يې تباه کړئ، او هر څۀ وکړئ د څۀ چې ما حکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19075, 'Jeremiah 50:22', 'Jeremiah', 50, 22, '&nbsp;په مُلک کښې دې د جنګ شور او ژړاګانې واورېدلے شى، او د لوئې تباهۍ آوازونه اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19076, 'Jeremiah 50:23', 'Jeremiah', 50, 23, '&nbsp;په ټوله دُنيا کښې د بابل لوئ او زورَور څټک څنګه ټوکړې ټوکړې شو. او وګورئ چې بابل څنګه په نورو قومونو کښې د وحشت مثال وګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19077, 'Jeremiah 50:24', 'Jeremiah', 50, 24, '&nbsp;اے بابليانو، ما تاسو ته لټ کېښودلو، خو تاسو پرې خبر نۀ وئ خو په کښې ګرفتار شوئ، ځکه چې تاسو د مالِک خُدائ خلاف جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19078, 'Jeremiah 50:25', 'Jeremiah', 50, 25, '&nbsp;مالِک خُدائ خپل د وسلې ګودام کولاو کړے دے او د خپل غضب وسله يې ترې راويستلې ده، ځکه چې مالِک خُدائ ربُ الافواج به دا د بابل خلاف د هغوئ په مُلک کښې استعمال کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19079, 'Jeremiah 50:26', 'Jeremiah', 50, 26, '&nbsp;د هرې خوا نه د هغۀ خلاف حمله وکړئ، او ګودامونه يې مات کړئ، او هغه لکه د غلې دانو په شان ډېرے کړئ. په مکمل توګه هغه تباه کړئ او هيڅ څوک په کښې ژوندى مۀ پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19080, 'Jeremiah 50:27', 'Jeremiah', 50, 27, '&nbsp;د هغوئ ټول غوَيان حلال کړئ، په دوئ دې افسوس وى ځکه د هغوئ د سزا او حساب ورځ او وخت رارسېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19081, 'Jeremiah 50:28', 'Jeremiah', 50, 28, '&nbsp;هغه کسانو ته غوږ شئ څوک چې د بابل نه راتښتېدلى دى، نو هغوئ په يروشلم کښې وائى چې مالِک خُدائ زمونږ خُدائ پاک د هغوئ نه څنګه انتقام اخلى څوک چې د هغۀ کور تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19082, 'Jeremiah 50:29', 'Jeremiah', 50, 29, '&nbsp;ټول لينده چلوونکى د بابل خلاف راجمع کړئ، محاصره يې کړئ چې يو کس هم درنه ونۀ تښتى. هغۀ ته د خپلو اعمالو په مطابق بدله ورکړئ، هغۀ سره هغه څۀ وکړئ کوم چې دۀ د نورو خلقو سره کړى دى. ځکه چې بابل د خپلې مغرورتيا په وجه د مالِک خُدائ د بنى اِسرائيلو د مقدس ذات خلاف سرکشى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19083, 'Jeremiah 50:30', 'Jeremiah', 50, 30, '&nbsp;مالِک خُدائ فرمائى چې، د هغۀ ځوانان به په کوڅو کښې راپرېوځى او قتل به شى، او د هغوئ فوجيان به په هغه ورځ ټول ختم کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19084, 'Jeremiah 50:31', 'Jeremiah', 50, 31, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، ګورئ، زۀ ستاسو خلاف يم، اے مغروره خلقو، ستاسو د سزا ورځ رارسېدلې ده هغه وخت چې زۀ تاسو له سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19085, 'Jeremiah 50:32', 'Jeremiah', 50, 32, '&nbsp;ستا کبرژن قوم به تيندک وخورى او راوبه غورزيږى، او هيڅ څوک به تاسو نۀ راوچتوى، زۀ به د هغۀ په ښارونو اور بل کړم او هغه به په خپل شا او خوا کښې ځان سره هر څۀ وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19086, 'Jeremiah 50:33', 'Jeremiah', 50, 33, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، د اِسرائيل او د يهوداه خلق مظلومان دى، هغوئ چې چا نيولى دى نو د هغوئ د پرېښودو نه اِنکار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19087, 'Jeremiah 50:34', 'Jeremiah', 50, 34, '&nbsp;خو د هغوئ بچ کوونکے ډېر زورَور دے، او مالِک خُدائ ربُ الافواج د هغۀ نوم دے. هغه به په سختۍ سره د هغوئ د مسئلې دفاع وکړى، او هغه به دوئ ته آرام ورکړى، خو د بابل خلق به نا آرامه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19088, 'Jeremiah 50:35', 'Jeremiah', 50, 35, '&nbsp;مالِک خُدائ فرمائى چې، د تباهۍ تُوره دې بابل تباه کړى. هغه دې د بابل ټول اوسېدونکى او د هغۀ آفسران او هوښياران خلق تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19089, 'Jeremiah 50:36', 'Jeremiah', 50, 36, '&nbsp;د هغوئ دروغژن نبيان به په جنګ کښې مړۀ شى، او هغوئ به بې‌وقوفان ثابت شى. د هغوئ تکړه فوجيان به په جنګ کښې قتل کړے شى، او هغوئ به سختو يرو ترخو کښې راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19090, 'Jeremiah 50:37', 'Jeremiah', 50, 37, '&nbsp;جنګ به د هغوئ خلاف د هغوئ آسونه او جنګى ګاډۍ تباه کړى او په هغۀ کښې د نورو مُلکونو فوجيان به هم تباه کړى. او هغوئ به د ښځو په شان بُزدله شى. او جنګ به د هغوئ خزانې تباه کړى، او لوټ به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19091, 'Jeremiah 50:38', 'Jeremiah', 50, 38, '&nbsp;د هغۀ د اوبو ذخيرې دې اوچې کړے شى. هغه به اوچې شى، ځکه چې ټول مُلک د بُتانو نه ډک شوے دے، او د هغه خلقو د بُتانو د يرې نه لکه د ليونو په شان عمل وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19092, 'Jeremiah 50:39', 'Jeremiah', 50, 39, '&nbsp;نو بيا به په بابل کښې د دشتو ځناور اوسيږى، او د ګيدړانو او ګونګيانو په کور به بدل شى. نو دا به بيا هيڅکله آباد نۀ شى او دا به همېشه دپاره شاړ پروت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19093, 'Jeremiah 50:40', 'Jeremiah', 50, 40, '&nbsp;لکه څنګه چې خُدائ پاک سدوم او عموره، سره د ګاونډيانو تباه کړل هم هغه شان به بابل هم تباه کړى. مالِک خُدائ فرمائى چې، نو هيڅ څوک به هلته نۀ اوسيږى او نۀ به يو انسان په کښې ژوند کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19094, 'Jeremiah 50:41', 'Jeremiah', 50, 41, '&nbsp;وګورئ، د شمال د خوا نه فوج راروان دے، يو لوئ قوم او ډېر بادشاهان د دُنيا د آخر نه راپاڅېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19095, 'Jeremiah 50:42', 'Jeremiah', 50, 42, '&nbsp;هغوئ په ليندو او نېزو باندې سمبال دى، او هغوئ ظالمان دى او هيڅ رحم په کښې نشته. کله چې هغوئ په خپلو آسونو باندې سوارۀ شى لکه د سمندر داسې غړمبار کوى، هغوئ جنګ ته په قطارونو کښې راروان دى چې په لور بابل باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19096, 'Jeremiah 50:43', 'Jeremiah', 50, 43, '&nbsp;د بابل بادشاه چې د دشمن د راتلو په حقله دا خبر واورېدو، نو د هغۀ لاسونه شل شول. هغه يرې او دردونو ونيولو، داسې درد لکه چې د ښځې د لنګون په وخت کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19097, 'Jeremiah 50:44', 'Jeremiah', 50, 44, '&nbsp;لکه څنګه چې يو زمرے د اُردن د جاړو بوټو نه د څرن زمکې ته راځى او په ګډو ورټوپ کوى، نو دغه شان به زۀ د بابل خلق د خپل مُلک نه وشړم، او زۀ به د خپلې خوښى مشر په کښې مقرر کړم. نو هغه به په دوئ حکومت وکړى. څوک زما په شان کېدلے شى؟ او يو مشر به هم زما خلاف ونۀ دريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19098, 'Jeremiah 50:45', 'Jeremiah', 50, 45, '&nbsp;نو بيا هغې منصوبې ته غوږ شه کومه چې مالِک خُدائ د بابليانو خلاف جوړه کړې ده، تر دې چې واړۀ ماشومان به د ګډورو په شان وشړلے شى، او د هغوئ د څرن ځايونه به وران کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19099, 'Jeremiah 50:46', 'Jeremiah', 50, 46, '&nbsp;زمکه به په دې چغو سورو سره په لړزان شى ”بابل قبضه کړے شوے دے.“ او د هغوئ د مايوسۍ ژړا به په ټوله دُنيا کښې واورېدلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19100, 'Jeremiah 51:1', 'Jeremiah', 51, 1, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”ګوره، زۀ به د بابل او د هغۀ د خلقو خلاف تباه کوونکې هوا راوچته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');